import { SPANS } from "./spans";
import { FPS } from "./timing";

/**
 * Cinematic shot scheduler. Gives the talking-head footage a directed rhythm
 * of WIDE establishing shots and TIGHT push-ins instead of a static frame —
 * the close/distance variety the brief asked for. One shot per kept span:
 *   • the first span of each chapter pulls back to a wide establishing 1.00
 *   • every other span cycles a pattern of medium/tight values
 * Between shots the scale eases smoothly (no pops); within a held shot it
 * breathes gently so even a long take never feels frozen.
 */

const PATTERN = [1.12, 1.04, 1.09, 1.15, 1.06, 1.11, 1.05, 1.13];

type Shot = {
  startF: number;
  endF: number;
  scale: number;
  oy: number;
  prevScale: number;
  prevOy: number;
};

const oyFor = (scale: number) => (scale >= 1.12 ? 33 : scale <= 1.01 ? 44 : 38);

const SHOTS: Shot[] = (() => {
  const shots: Shot[] = [];
  let prevScale = 1.03;
  let prevOy = 40;
  let pi = 0;
  for (let i = 0; i < SPANS.length; i++) {
    const s = SPANS[i];
    const sectionStart = i === 0 || SPANS[i - 1].section !== s.section;
    let scale: number;
    if (sectionStart) {
      scale = 1.0;
      pi = 0;
    } else {
      scale = PATTERN[pi % PATTERN.length];
      pi += 1;
    }
    const oy = oyFor(scale);
    shots.push({
      startF: Math.round(s.cutStart * FPS),
      endF: Math.round(s.cutEnd * FPS),
      scale,
      oy,
      prevScale,
      prevOy,
    });
    prevScale = scale;
    prevOy = oy;
  }
  return shots;
})();

const TR = 22; // transition length in frames (~0.73s)

const easeInOutQuad = (p: number) =>
  p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;

export const shotAt = (
  cutFrame: number
): { scale: number; ox: number; oy: number } => {
  let idx = 0;
  for (let i = 0; i < SHOTS.length; i++) {
    if (cutFrame >= SHOTS[i].startF) idx = i;
    else break;
  }
  const shot = SHOTS[idx];
  const local = cutFrame - shot.startF;

  let scale: number;
  let oy: number;
  if (local < TR) {
    const e = easeInOutQuad(Math.max(0, local) / TR);
    scale = shot.prevScale + (shot.scale - shot.prevScale) * e;
    oy = shot.prevOy + (shot.oy - shot.prevOy) * e;
  } else {
    const dur = Math.max(1, shot.endF - shot.startF - TR);
    const held = local - TR;
    // gentle breathing during the held portion of the shot
    scale = shot.scale + Math.sin((held / dur) * Math.PI) * 0.012;
    oy = shot.oy;
  }
  // never below 1.0 (would reveal frame edges)
  return { scale: Math.max(1.0, scale), ox: 50, oy };
};
