/**
 * State of a given tip at a given global frame.
 * - upcoming: not yet introduced → frosted / locked (drives curiosity)
 * - active:   currently being discussed → sharp, highlighted
 * - done:     already covered → dimmed with a checkmark
 */
export type TipState = "upcoming" | "active" | "done";

export const tipStateAt = (tipIndex: number, frame: number): TipState => {
  const start = TIPS[tipIndex].activeAt;
  const nextStart = TIPS[tipIndex + 1]?.activeAt ?? Infinity;
  if (frame < start) return "upcoming";
  if (frame < nextStart) return "active";
  return "done";
};
