/**
 * Timing map for "0009 — How AI Reinvented Insurance".
 *
 * The footage in public/0009-ai-reinvented-insurance-cut.mp4 is a baked RADIO
 * EDIT (true CFR-30, so audio stays in lip-sync): best take of every line, all
 * flubs + dead air removed. Built by build_edl.py from the SRT + silencedetect.
 *
 * EVERY overlay below is anchored to the SPOKEN LINE it belongs to via `at()`,
 * which looks the line up in the auto-generated SPANS table. So when the cut
 * changes (a take swapped, a span dropped) and spans.ts is regenerated, every
 * stat, cutaway, section card and lesson badge follows automatically — no
 * hand-re-timing, nothing drifts out of sync.
 */
import { SPANS } from "./spans";

export const FPS = 30;
export const sec = (s: number) => Math.round(s * FPS);

/** Baked cut length — true CFR-30 (ffprobe -count_frames: 12910 == 430.33*30). */
export const TALK_SECONDS = 430.333;
export const TALK_FRAMES = 12910;

export const THUMBNAIL_FRAMES = sec(1);
export const COMPOSITION_FRAMES = THUMBNAIL_FRAMES + TALK_FRAMES;

/* ───────────────────── span anchoring (single source) ────────────────── */
/** cut-time (s) of the first span whose spoken label contains `needle`. */
export const at = (needle: string): number => {
  const n = needle.toLowerCase();
  const s = SPANS.find((sp) => sp.label.toLowerCase().includes(n));
  if (!s) throw new Error(`[timing] no span matches "${needle}"`);
  return s.cutStart;
};
/** cut-time (s) the line ends. */
export const endOf = (needle: string): number => {
  const n = needle.toLowerCase();
  const s = SPANS.find((sp) => sp.label.toLowerCase().includes(n));
  if (!s) throw new Error(`[timing] no span matches "${needle}"`);
  return s.cutEnd;
};
/** cut-time (s) the first span of a section begins. */
export const sectionStart = (section: string): number => {
  const s = SPANS.find((sp) => sp.section === section);
  if (!s) throw new Error(`[timing] no section "${section}"`);
  return s.cutStart;
};

/* ────────────────────────────── chapters ────────────────────────────── */
export type Chapter = { short: string; at: number; accent: "teal" | "amber" };

export const CHAPTERS: Chapter[] = [
  { short: "Insurance", at: sectionStart("insurance"), accent: "teal" },
  { short: "Customer Service", at: sectionStart("service"), accent: "amber" },
  { short: "Fraud & Rails", at: sectionStart("fraud"), accent: "teal" },
  { short: "What It Means", at: sectionStart("lessons"), accent: "amber" },
];

export const RAIL_IN = sec(9);

export type ChapterState = "upcoming" | "active" | "done";
export const chapterStateAt = (i: number, frame: number): ChapterState => {
  const start = sec(CHAPTERS[i].at);
  const next = CHAPTERS[i + 1] ? sec(CHAPTERS[i + 1].at) : Infinity;
  if (frame < start) return "upcoming";
  if (frame < next) return "active";
  return "done";
};

