// Shared surface + motion tokens for The Platform overlay system.
//
// Centralising these keeps every panel visually consistent (one frosted-ink
// surface, one shadow language, one spring feel) and makes a re-skin a
// single-file change. Components import these instead of re-deriving them.
import { colors } from "./colors";

/** The frosted-ink legibility panel used by every overlay over footage. */
export const panel = {
  background: `${colors.ink}F0`,
  border: `1.5px solid ${colors.yellow}33`,
  borderRadius: 24,
  boxShadow: `0 28px 70px -24px rgba(0,0,0,0.78), 0 0 0 6px ${colors.ink}40`,
} as const;

/** A glow-lifted variant for the single "spark" element (active badge, stat). */
export const sparkShadow = `0 18px 44px -12px ${colors.yellow}55, 0 0 0 5px ${colors.yellow}26`;

/** Consistent entrance spring across the system (panels slide + settle). */
export const ENTER_SPRING = { damping: 21, stiffness: 84 } as const;
/** Snappier spring for staggered child elements (list items, captions). */
export const CHILD_SPRING = { damping: 24, stiffness: 92 } as const;

/** Safe margins (px) inside the 1920×1080 frame. */
export const MARGIN = { side: 80, top: 150, bottom: 150 } as const;
